import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type RepaintHouseProps = Record<string, any>;

const RepaintHouse: React.FC<RepaintHouseProps> = ({
  backgroundColor = "#1E1E1E",
  transparentBackground = false,
  durationInSeconds = 8,
  originalWallColor = "#DDB892",
  newWallColor = "#FFFFFF",
  floorColor = "#8B4513",
  baseboardColor = "#F4F4F4",
  doorColor = "#ECF0F1",
  title = "A Brighter Space!",
  subtitle = "Refresh your interior with clean white walls.",
}) => {
  
  useFontLoader(["Montserrat", "Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const sceneScale = spring({
    frame: frame - 10,
    fps,
    config: { damping: 14 }
  });

  const rollerEnter = spring({ 
    frame: frame - 40, 
    fps, 
    config: { damping: 15 } 
  });
  
  const rollerExit = spring({ 
    frame: frame - 155, 
    fps, 
    config: { damping: 15 } 
  });

  // Calculate Roller X Position (Sweeps in from right, aligns to x=0 to cover the whole wall, sweeps out to left)
  const currentRollerX = interpolate(rollerEnter, [0, 1], [300, 0]) - interpolate(rollerExit, [0, 1], [0, 300]);

  // Calculate Paint Y Position (Moves top to bottom, covering the wall height)
  const paintY = interpolate(frame, [60, 150], [-20, 180], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Sparkle Animations
  const sparkle1Scale = spring({ frame: frame - 160, fps, config: { damping: 10 } });
  const sparkle2Scale = spring({ frame: frame - 165, fps, config: { damping: 10 } });
  const sparkle3Scale = spring({ frame: frame - 170, fps, config: { damping: 10 } });

  const sparkle1Opacity = interpolate(frame, [190, 210], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const sparkle2Opacity = interpolate(frame, [195, 215], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const sparkle3Opacity = interpolate(frame, [200, 220], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const sparklePath = "M 0,-15 Q 0,0 15,0 Q 0,0 0,15 Q 0,0 -15,0 Q 0,0 0,-15";

  // Text Animations
  const titleY = interpolate(spring({ frame: frame - 165, fps, config: { damping: 12 } }), [0, 1], [40, 0]);
  const titleOpacity = interpolate(frame, [165, 180], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const subtitleY = interpolate(spring({ frame: frame - 175, fps, config: { damping: 12 } }), [0, 1], [40, 0]);
  const subtitleOpacity = interpolate(frame, [175, 190], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Layout calculations
  const isPortrait = height > width;
  const svgSize = Math.min(width, height) * 0.85;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
      
      {/* Container for SVG and Text */}
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", transform: `translateY(${isPortrait ? "-5%" : "0%"})`, transition: "none" }}>
        
        {/* The Interior Room SVG Scene */}
        <div style={{ width: svgSize, height: svgSize, position: "relative", transition: "none" }}>
          <svg viewBox="0 0 200 200" style={{ width: "100%", height: "100%", overflow: "visible", transition: "none" }}>
            <defs>
              <clipPath id="wipe-mask">
                <rect x="0" y="0" width="200" height={Math.max(0, paintY)} />
              </clipPath>
            </defs>

            <g transform={`scale(${sceneScale})`} style={{ transformOrigin: "100px 200px" }}>
              
              {/* Original Wall */}
              <rect x="0" y="0" width="200" height="170" fill={originalWallColor} />
              
              {/* Painted Wall (Revealed by Mask) */}
              <rect x="0" y="0" width="200" height="170" fill={newWallColor} clipPath="url(#wipe-mask)" />

              {/* Floor */}
              <rect x="0" y="170" width="200" height="30" fill={floorColor} />
              {/* Floor Perspective Shadow */}
              <polygon points="0,170 200,170 220,200 -20,200" fill="#000000" opacity="0.05" />

              {/* Baseboard */}
              <rect x="0" y="160" width="200" height="10" fill={baseboardColor} />
              <line x1="0" y1="160" x2="200" y2="160" stroke="#000000" strokeWidth="1" opacity="0.1" />
              <line x1="0" y1="170" x2="200" y2="170" stroke="#000000" strokeWidth="1" opacity="0.15" />

              {/* Window Showing Outside */}
              <g transform="translate(130, 40)">
                <rect x="-4" y="-4" width="48" height="68" fill={baseboardColor} />
                <rect x="0" y="0" width="40" height="60" fill="#87CEEB" />
                <line x1="20" y1="0" x2="20" y2="60" stroke={baseboardColor} strokeWidth="3" />
                <line x1="0" y1="30" x2="40" y2="30" stroke={baseboardColor} strokeWidth="3" />
                {/* Sunlight cast into room */}
                <polygon points="0,60 20,100 60,100 40,60" fill="#ffffff" opacity="0.1" />
              </g>

              {/* Interior Door */}
              <g transform="translate(30, 60)">
                <rect x="-4" y="-4" width="58" height="104" fill={baseboardColor} />
                <rect x="0" y="0" width="50" height="100" fill={doorColor} />
                <rect x="8" y="8" width="34" height="38" rx="2" fill="#000000" opacity="0.05" />
                <rect x="8" y="54" width="34" height="38" rx="2" fill="#000000" opacity="0.05" />
                <circle cx="40" cy="50" r="3" fill="#E8A317" />
              </g>

              {/* Potted Plant Detail */}
              <g transform="translate(165, 150)">
                <path d="M 10,10 Q -5,-5 5,-15 Q 15,-5 10,10" fill="#2E8B57" />
                <path d="M 10,10 Q 5,-10 15,-20 Q 25,-10 10,10" fill="#3CB371" />
                <path d="M 10,10 Q 25,-5 15,-15 Q 5,-5 10,10" fill="#2E8B57" />
                <polygon points="4,10 16,10 14,20 6,20" fill="#D2691E" />
              </g>

              {/* Paint Roller (Translates down with the wipe) */}
              {frame > 30 && frame < 180 && (
                <g transform={`translate(${currentRollerX}, ${paintY - 20})`}>
                  {/* Handle Wire */}
                  <path d="M 200,10 L 220,10 L 220,40 L 110,40 L 110,80" fill="none" stroke="#7f8c8d" strokeWidth="5" strokeLinejoin="round" />
                  {/* Handle Grip */}
                  <rect x="100" y="80" width="20" height="50" rx="10" fill="#2c3e50" />
                  {/* Roller Sponge */}
                  <rect x="0" y="0" width="200" height="20" rx="8" fill={newWallColor} />
                  {/* Subtle paint wetness line on roller */}
                  <path d="M 10,10 L 190,10" fill="none" stroke="#000000" strokeWidth="4" strokeLinecap="round" opacity="0.1" />
                </g>
              )}

              {/* Post-paint Sparkles */}
              <g transform={`translate(50, 80) scale(${sparkle1Scale})`} opacity={sparkle1Opacity}>
                <path d={sparklePath} fill="#F1C40F" />
              </g>
              <g transform={`translate(150, 120) scale(${sparkle2Scale})`} opacity={sparkle2Opacity}>
                <path d={sparklePath} fill="#F1C40F" />
              </g>
              <g transform={`translate(100, 40) scale(${sparkle3Scale})`} opacity={sparkle3Opacity}>
                <path d={sparklePath} fill="#F1C40F" />
              </g>

            </g>
          </svg>
        </div>

        {/* Text Section */}
        <div style={{ 
          marginTop: isPortrait ? 60 : 30, 
          textAlign: "center", 
          display: "flex", 
          flexDirection: "column", 
          gap: isPortrait ? "1rem" : "0.5rem",
          width: "90%",
          transition: "none"
        }}>
          <h1 style={{
            fontFamily: "Montserrat",
            fontSize: isPortrait ? "4rem" : "2.8rem",
            fontWeight: 800,
            color: "#ffffff",
            margin: 0,
            lineHeight: 1.1,
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            textShadow: "0 4px 12px rgba(0,0,0,0.15)",
            transition: "none"
          }}>
            {title}
          </h1>
          <p style={{
            fontFamily: "Inter",
            fontSize: isPortrait ? "1.8rem" : "1.4rem",
            fontWeight: 400,
            color: "#ffffff",
            margin: 0,
            opacity: subtitleOpacity,
            transform: `translateY(${subtitleY}px)`,
            textShadow: "0 2px 8px rgba(0,0,0,0.1)",
            transition: "none"
          }}>
            {subtitle}
          </p>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default RepaintHouse;